// FF90-01 Source Intake — Input normalizer
// Accepts a normalized job shape and produces a canonical source record.
// NEVER fabricates timestamps; if the source has no published_at, we
// mark it null and the downstream dedupe step decides.
const item = items[0].json;
const canonical = {
  canonical_url: typeof item.source_url === 'string' ? item.source_url.trim() : '',
  source_title: typeof item.source_title === 'string' ? item.source_title : '',
  publisher: typeof item.publisher === 'string' ? item.publisher : '',
  published_at: typeof item.published_at === 'string' ? item.published_at : null,
  competition: typeof item.competition === 'string' ? item.competition : '',
  teams: Array.isArray(item.teams) ? item.teams : [],
  people: Array.isArray(item.people) ? item.people : [],
  source_text: typeof item.source_text === 'string' ? item.source_text : '',
  source_type: typeof item.source_type === 'string' ? item.source_type : 'other',
  raw: item,
};
// Compute source_id deterministically from canonical_url + source_title.
const crypto = require('crypto');
const h = crypto.createHash('sha256');
h.update(canonical.canonical_url || canonical.source_title || '');
h.update('\u0000');
h.update(canonical.published_at || '');
canonical.source_id = 'src:' + h.digest('hex').slice(0, 48);
return [{ json: canonical }];

// Phase 18G — duplicate stop. Re-emit canonical envelope with
// pipeline_status='duplicate'. Preserve source_* from upstream so
// MASTER sees the dedupe context.
const src = $('Normalize source').item.json || {};
const dedupe = $('POST /api/automation/deduplicate').item.json || {};
return [{
  json: {
    ...(src.raw || {}),
    run_id: dedupe.run_id || null,
    editorial_item_id: null,
    source_id: src.source_id || null,
    source_url: src.canonical_url || null,
    source_title: src.source_title || null,
    publisher: src.publisher || null,
    published_at: src.published_at || null,
    source_type: src.source_type || null,
    source_text: src.source_text || null,
    pipeline_stage: 'source_intake',
    pipeline_status: 'duplicate',
    metadata: { duplicate: true },
  },
}];

// Phase 18G — terminal promote node. Re-emits the canonical
// pipeline envelope so MASTER can extract run_id, editorial_item_id,
// and source context without losing data to the Audit-log response.
//
// Merge rule: previous envelope + fields explicitly set by this stage.
//
// Upstream payload (from POST /api/automation/editorial-item) carries
// editorial_item_id + run_id; merge with the original Normalize-source
// output which carries source_* fields.
//
// We use cross-node refs to read fields that other nodes produced.
const up = $('POST /api/automation/editorial-item').item.json;
const src = $('Normalize source').item.json || {};
return [{
  json: {
    ...(src.raw || {}),
    run_id: up.run_id || null,
    editorial_item_id: up.editorial_item_id || null,
    source_id: src.source_id || null,
    source_url: src.canonical_url || null,
    source_title: src.source_title || null,
    publisher: src.publisher || null,
    published_at: src.published_at || null,
    source_type: src.source_type || null,
    source_text: src.source_text || null,
    pipeline_stage: 'source_intake',
    pipeline_status: 'accepted',
    metadata: {},
  },
}];
